UPDATE wms_inventory_batch
warehouse_id = #{warehouseId}, location_id = #{locationId}, product_id = #{productId}, batch_no = #{batchNo}, supplier_id = #{supplierId}, quantity = #{quantity}, available_quantity = #{availableQuantity}, locked_quantity = #{lockedQuantity}, frozen_quantity = #{frozenQuantity}, unit = #{unit}, produce_date = #{produceDate}, expire_date = #{expireDate}, inbound_date = #{inboundDate}, inventory_status = #{inventoryStatus}, inspection_status = #{inspectionStatus}, cost_price = #{costPrice}, remark = #{remark}, update_by = #{updateBy}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT

FROM wms_inventory_batch ib
LEFT JOIN wms_product p ON ib.product_id = p.id
LEFT JOIN wms_location l ON ib.location_id = l.id
LEFT JOIN wms_supplier s ON ib.supplier_id = s.id

    AND ib.warehouse_id = #{warehouseId}
    AND ib.location_id = #{locationId}
    AND EXISTS (SELECT 1 FROM wms_location l2 WHERE l2.id = ib.location_id AND l2.area_id = #{areaId})
    AND ib.product_id = #{productId}
    AND p.product_code LIKE CONCAT('%', #{productCode}, '%')
    AND p.product_name LIKE CONCAT('%', #{productName}, '%')
    AND ib.batch_no LIKE CONCAT('%', #{batchNo}, '%')
    AND ib.supplier_id = #{supplierId}

        AND ib.inventory_status IN

            #{status}


    AND ib.quantity > 0
    AND ib.produce_date >= #{produceDateStart}
    AND ib.produce_date <= #{produceDateEnd}
    AND ib.expire_date >= #{expireDateStart}
    AND ib.expire_date <= #{expireDateEnd}
    AND ib.inbound_date >= #{inboundDateStart}
    AND ib.inbound_date <= #{inboundDateEnd}



        ORDER BY ${orderBy} ${orderDirection}


        ORDER BY ib.create_time DESC


LIMIT #{pageNum}, #{pageSize}

SELECT

FROM wms_inventory_batch
WHERE warehouse_id = #{warehouseId}
AND product_id = #{productId}
AND available_quantity > 0
AND inventory_status != 4


        ORDER BY expire_date ASC


        AND batch_no = #{specifyBatchNo}
        ORDER BY create_time ASC


        ORDER BY create_time ASC
